        nft.mint(address(c), tokenId);

        PrivatePool refPool = new PrivatePool(address(this), address(this), address(this));

        refPool.initialize(
            address(0x1),
            address(nft),
            1000 ether,
            1000,
            1,
            100,
            bytes32(0),
            false,
            false
        );

        address feeToken = refPool.flashFeeToken();

        TestERC20 baseToken = new TestERC20();






        assertTrue(refPool.baseToken() != address(0), "Reference should have non-zero baseToken");

