contract TestNFT {
    mapping(uint256 => address) public _ownerOf;
    function mint(address to, uint256 id) external { _ownerOf[id] = to; }
    function ownerOf(uint256 id) external view returns (address) { return _ownerOf[id]; }
    function safeTransferFrom(address from, address to, uint256 id) external { _ownerOf[id] = to; }
    function supportsInterface(bytes4) external pure returns (bool) { return false; }
}

contract TestERC20 {
    mapping(address => uint256) public balanceOf;
    function transferFrom(address, address, uint256) external returns (bool) { return true; }
    function transfer(address, uint256) external returns (bool) { return true; }
    function approve(address, uint256) external returns (bool) { return true; }
    function decimals() external pure returns (uint8) { return 18; }
}
